import test from 'node:test';import assert from 'node:assert/strict';import {createRealtimeUpload} from './realtimeClient.js';
const tick=()=>new Promise(r=>setImmediate(r));
test('uploads before stop, bounded batches and finish after last chunk',async()=>{const calls=[];const api=async(route,o)=>{calls.push([route,o]);return route.endsWith('/realtime')?{streamId:'stream'}:{ok:true};};const u=createRealtimeUpload({api,sessionId:'s',revision:1,clientTurnId:'t'});u.push(new Uint8Array(12000));await tick();assert.ok(calls.some(([r])=>r.includes('/chunk')));u.push(new Uint8Array(1000));await u.finish();assert.match(calls.at(-1)[0],/finish$/);assert.equal(calls.at(-1)[1].body.count,2);assert.deepEqual(calls.filter(([r])=>r.includes('/chunk')).map(([r])=>r.split('sequence=')[1]),['0','1']);});
test('cancel during start cancels returned session without sending queued audio',async()=>{let resolve;const calls=[];const u=createRealtimeUpload({api:(route)=>{calls.push(route);return route.endsWith('/realtime')?new Promise(r=>resolve=r):Promise.resolve({});},sessionId:'s',revision:1,clientTurnId:'t'});u.push(new Uint8Array(10000));u.cancel();resolve({streamId:'late'});await tick();assert.equal(calls.some(r=>r.includes('/chunk')),false);assert.ok(calls.includes('/realtime/late/cancel'));await assert.rejects(u.finish());});
test('upload failure and overflow never retry automatically',async()=>{let resolve,requests=0;const u=createRealtimeUpload({api:()=>new Promise(r=>resolve=r),sessionId:'s',revision:1,clientTurnId:'t'});assert.throws(()=>u.push(new Uint8Array(300000)));resolve({streamId:'overflow'});await tick();const v=createRealtimeUpload({api:async r=>{if(r.endsWith('/realtime'))return{streamId:'x'};if(r.includes('/chunk')){requests++;throw Error('offline');}return{};},sessionId:'s',revision:1,clientTurnId:'t'});v.push(new Uint8Array(10000));await tick();await assert.rejects(v.finish(),/offline/);assert.equal(requests,1);});
test('abort during final upload drain sends cancel without waiting for the chunk response',async()=>{let release;const calls=[];const u=createRealtimeUpload({api:async r=>{calls.push(r);if(r.endsWith('/realtime'))return{streamId:'x'};if(r.includes('/chunk'))await new Promise(r=>release=r);return{};},sessionId:'s',revision:1,clientTurnId:'t'});u.push(new Uint8Array(10000));await tick();const ctrl=new AbortController();const done=u.finish({signal:ctrl.signal});const check=assert.rejects(done);ctrl.abort();await tick();assert.ok(calls.includes('/realtime/x/cancel'));release();await check;assert.equal(calls.some(r=>r.endsWith('/finish')),false);});
test('cancelled start cannot report a late authentication error to a new account',async()=>{let reject;const errors=[];const u=createRealtimeUpload({api:()=>new Promise((_,r)=>reject=r),sessionId:'s',revision:1,clientTurnId:'t',onError:e=>errors.push(e)});u.cancel();reject(Object.assign(Error('old account'),{code:'ACCOUNT_CONTEXT_MISMATCH',status:401}));await tick();assert.deepEqual(errors,[]);});
